Method.Implementation:
set stat = $$$OK
try
	{
		Do ..JavaGateway.%Import(..JarFile) 

		Do ##class(org.ihc.itf.crypto.IHCCryptoUtils).setDebugSet(..JavaGateway, ..JarDebug)

		$$$TRACE("OnMessage: " _ pRequest.operation)
	if (pRequest.operation = "EncryptFile")
	{
		Do ##class(org.ihc.itf.crypto.IHCCrypto).EncryptFile(..JavaGateway, pRequest.inputDirectory, 
		pRequest.inputFilename, pRequest.outputDirectory, pRequest.outputFilename, 
		pRequest.publicKeyRingFile, pRequest.secretKeyRingFile, pRequest.publicKeyName, pRequest.secretKeyRingPwd)	
	}
	elseif (pRequest.operation = "DecryptFile")
	{
		Do ##class(org.ihc.itf.crypto.IHCCrypto).DecryptFile(..JavaGateway, pRequest.inputDirectory,
		pRequest.inputFilename, pRequest.outputDirectory, pRequest.outputFilename,
		pRequest.publicKeyRingFile, pRequest.secretKeyRingFile, pRequest.secretKeyRingPwd)	
	}

	else
	{
		set stat = $$$ERROR("Invalid operation")
	}
}catch errobj {
    $$$LOGERROR( "Error in IHCCryptoData: "  _ errobj.AsSystemError() _ " _ data: " _ errobj.Data _ "; code:" _ errobj.Code)
    set stat = $$$ERROR("Exception in IHCCryptoData: " _ errobj.AsSystemError() _ " _ data: " _ errobj.Data _ "; code:" _ errobj.Code)
}
return stat
